 useEffect(()=>()=>{streamRef.current?.getTracks().forEach(t=>t.stop());liveStreamRef.current?.getTracks().forEach(t=>t.stop());liveWsRef.current?.close();void liveContextRef.current?.close();if(audioUrlRef.current)URL.revokeObjectURL(audioUrlRef.current)},[]);
 const completed=new Set(data.completed); const totalDone=data.completed.length; const levelProgress=curriculum.map(l=>({...l,done:l.units.filter(u=>completed.has(u.id)).length})); const currentLevel=levelProgress.find(l=>l.units.some(u=>!completed.has(u.id)))||levelProgress[levelProgress.length-1];
