 async function requestMic(){try{const stream=await navigator.mediaDevices.getUserMedia({audio:deviceId?{deviceId:{exact:deviceId},echoCancellation:true,noiseSuppression:true}:true});streamRef.current?.getTracks().forEach(t=>t.stop());streamRef.current=stream;setPermission('granted');const ds=await navigator.mediaDevices.enumerateDevices();setDevices(ds.filter(d=>d.kind==='audioinput'));const track=stream.getAudioTracks()[0];if(!recorder.current||recorder.current.state==='inactive')setDeviceId(track.getSettings().deviceId||'');return stream;}catch{setPermission('denied');toast.error('Izin mikrofon belum diberikan. Cek pengaturan browser.');return null;}}
